gvy(){return"\u0625\u0644\u063a\u0627\u0621 \u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gpe(){return"\u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gtB(){return"\u064a\u0639\u0631\u0636 \u0639\u062f\u062f \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0641\u064a \u0627\u0644\u0625\u062d\u0635\u0627\u0626\u064a\u0627\u062a"},
gtA(){return"\u0623\u0636\u0641 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0641\u064a \u0627\u0644\u062d\u0633\u0627\u0628 \u0644\u0644\u062a\u0641\u0639\u064a\u0644"},
gr0(){return"\u0627\u0644\u0645\u0641\u0636\u0644\u0629"},
gqo(){return"\u0639\u0631\u0636 \u0627\u0644\u0645\u0632\u064a\u062f"},
gAg(){return"\u0645\u0641\u0636\u0644\u062a\u064a"},
gAh(){return"\u0627\u0628\u062d\u062b \u0639\u0646 \u0645\u0642\u0637\u0648\u0639\u0629 \u0623\u0648 \u0641\u0646\u0627\u0646"},
gA2(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u0641\u0636\u0644\u0627\u062a \u0628\u0639\u062f. \u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0642\u0644\u0628 \u0641\u064a \u0623\u064a \u0645\u0642\u0637\u0648\u0639\u0629 \u0644\u0625\u0636\u0627\u0641\u062a\u0647\u0627."},
