gr2(){return"\u0627\u0644\u0623\u0642\u062f\u0645"},
gr1(){return"\u0627\u0644\u0641\u0646\u0627\u0646 \u0623-\u064a"},
gr4(){return"\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0623-\u064a"},
gAf(){return"\u064a\u062f\u0648\u064a"},
goa(){return"\u0645\u062c\u0644\u062f \u062c\u062f\u064a\u062f"},
gAd(){return"\u0627\u0633\u0645 \u0627\u0644\u0645\u062c\u0644\u062f"},
