n5(a){return"\u0639\u0636\u0648 \u0645\u0646\u0630 "+a},
u5(a){return"\u0627\u0644\u0625\u0635\u062f\u0627\u0631 v"+a+" \u0645\u062a\u0627\u062d"},
po(a){return"\u062a\u062d\u062f\u064a\u062b v"+a},
yI(a,b){return"\u062a\u062d\u062f\u064a\u062b "+(b?"\u062a\u062c\u0631\u064a\u0628\u064a":"\u062c\u062f\u064a\u062f")+": v"+a},
