vr(a){return"\u062a\u0645\u062a \u0625\u0636\u0627\u0641\u0629 @"+a+" \u0628\u0646\u062c\u0627\u062d."},
vE(a,b){return"\u062d\u0633\u0627\u0628\u0627\u062a\u064a ("+a+"/"+b+")"},
